internal sealed class Options {
 public string Mode="install",Destination=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Relay"),Data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".relay-data"),BrowserCache="";
