 public static Options Parse(string[] args){var value=new Options();for(int i=0;i<args.Length;i++){string name=args[i];if(name=="--launch")value.Mode="launch";else if(name=="--uninstall"||name=="--uninstall-worker")value.Mode="uninstall";else if(name=="--silent")value.Silent=true;else if(name=="--no-integrations")value.NoIntegrations=true;else if(name=="--no-browser")value.NoBrowser=true;else if(name=="--start-at-signin")value.AutoStart=true;else if((name=="--destination"||name=="--data"||name=="--port"||name=="--browser-cache")&&i+1<args.Length){string next=args[++i];if(name=="--destination")value.Destination=next;else if(name=="--data")value.Data=next;else if(name=="--browser-cache")value.BrowserCache=next;else value.Port=int.Parse(next);}else throw new Exception("Unknown setup option.");}return value;}
